parameters.jsCode:
const items = $input.all();
let mergedContent = '';
const toc = [];
for (let i = 0; i < items.length; i++) {
  const content = items[i].json.data || items[i].json.body || '';
  const title = items[i].json.title || `Document ${i + 1}`;
  toc.push(`${i + 1}. ${title}`);
  mergedContent += `<h2>${title}</h2>\n${content}\n<hr/>\n`;
}
const finalHtml = `<html><body><h1>Merged Document</h1><h3>Table of Contents</h3><ul>${toc.map(t => `<li>${t}</li>`).join('')}</ul><hr/>${mergedContent}</body></html>`;
return [{ json: { mergedHtml: finalHtml, documentCount: items.length, tableOfContents: toc } }];

